    C(CON, "x3-ph-verite2", ["Qu'est-ce que la vérité ?", "Plusieurs définitions coexistent."],
      ["Vérité-correspondance : accord de la pensée avec la chose (Thomas d'Aquin).", "Vérité-cohérence : non-contradiction d'un ensemble de propositions (logique, maths).", "Vérité pragmatique : est vrai ce qui réussit (William James).", "Relativisme (Protagoras) contre recherche d'une vérité universelle (Platon)."],
      [("« Il pleut »", ["Cette phrase est vraie si, en ce moment, il pleut réellement.", "C'est la vérité comme correspondance."])],
      "Les définitions de la vérité.",
      [("La vérité-correspondance est :", "l'accord de la pensée avec la réalité", "la cohérence logique", "l'utilité", "l'opinion majoritaire", "Adéquation."),
       ("Le pragmatisme (James) définit le vrai comme :", "ce qui réussit dans l'action", "ce qui est cohérent", "ce que dit l'autorité", "ce qui est ancien", "Utilité."),
       ("« L'homme est la mesure de toutes choses » est de :", "Protagoras", "Platon", "Kant", "Descartes", "Relativisme."),
       ("En mathématiques, la vérité est surtout :", "cohérence (démonstration)", "correspondance avec les sens", "utilité", "tradition", "Vérité formelle.")], title="Les définitions de la vérité"),
